#!/usr/bin/env node
// build-site-facts.mjs - derive the numbers the site prints from the data
// files that define them, so copy cannot drift from the catalog.
//
// Output: src/lib/litespm/site-facts.json (committed; regenerated by predev,
// build and pretype-check). Counts that used to be typed by hand in six files
// (52 hosts, 47 remote-capable, 81 skill targets, 13 bridge tools, 69k
// listings, the npm version) are read from hosts.json, skill-targets.json,
// release.json and published-cli.json.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const read = (file) => JSON.parse(readFileSync(path.join(root, "data", file), "utf8"));

const hosts = read("hosts.json");
const targets = read("skill-targets.json");
const release = read("release.json");
const cli = read("published-cli.json");

const remote = hosts.filter((h) => h.remote === true);
const localOnly = hosts.filter((h) => h.remote !== true);

const facts = {
  hosts: hosts.length,
  remoteHosts: remote.length,
  localOnlyHosts: localOnly.map((h) => h.id).sort(),
  localOnlyHostNames: localOnly.map((h) => h.name).sort(),
  skillTargets: targets.length,
  listings: release.itemCount,
  mcpServers: release.mcpServersCount,
  skills: release.agentSkillsCount,
  plugins: release.pluginsCount,
  releaseId: release.releaseId,
  // npm dist-tags.latest. The repository may be ahead of this (unreleased).
  npmVersion: cli.version,
  // The bridge's MCP tool count is a property of the Go binary, not of any
  // data file; keep the single source here and in STATUS.md.
  bridgeTools: 13,
};

const out = path.join(root, "src", "lib", "litespm", "site-facts.json");
mkdirSync(path.dirname(out), { recursive: true });
const next = `${JSON.stringify(facts, null, 2)}\n`;
let prev = "";
try {
  prev = readFileSync(out, "utf8");
} catch {}
if (prev !== next) writeFileSync(out, next);
console.log(`site-facts: ${facts.hosts} hosts (${facts.remoteHosts} remote), ${facts.skillTargets} skill targets, ${facts.listings} listings, npm ${facts.npmVersion}`);
